def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    from collections import Counter

    # 1. Find background color
    bg_count = Counter()
    for r in range(rows):
        for c in range(cols):
            bg_count[grid[r][c]] += 1
    bg = bg_count.most_common(1)[0][0]

    # 2. Find connected components (4-connectivity)
    dirs = [(-1,0), (1,0), (0,-1), (0,1)]
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and not visited[r][c]:
                comp = []
                stack = [(r,c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    comp.append((cr, cc))
                    for dr, dc in dirs:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] != bg:
                                visited[nr][nc] = True
                                stack.append((nr, nc))
                components.append(comp)

    # 3. Find main pattern component (largest bounding box area)
    main_comp = None
    max_area = -1
    for comp in components:
        min_r = min(r for r,c in comp)
        max_r = max(r for r,c in comp)
        min_c = min(c for r,c in comp)
        max_c = max(c for r,c in comp)
        area = (max_r - min_r + 1) * (max_c - min_c + 1)
        if area > max_area:
            max_area = area
            main_comp = comp
        elif area == max_area:
            # Prefer larger component size if areas tie
            if len(comp) > len(main_comp):
                main_comp = comp

    if main_comp is None:
        return grid  # No non-background pixels

    # 4. Extract subgrid from main pattern's bounding box
    min_r = min(r for r,c in main_comp)
    max_r = max(r for r,c in main_comp)
    min_c = min(c for r,c in main_comp)
    max_c = max(c for r,c in main_comp)

    h = max_r - min_r + 1
    w = max_c - min_c + 1
    subgrid = [grid[r][min_c: max_c+1] for r in range(min_r, max_r+1)]

    # 5. Identify markers
    markers = []
    main_set = set(main_comp)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and (r,c) not in main_set:
                markers.append((r,c))

    # 6. Construct output
    output = [[bg]*cols for _ in range(rows)]

    # Fill main pattern
    for r,c in main_set:
        output[r][c] = grid[r][c]

    # Paste subgrid at each marker
    for mr, mc in markers:
        for dr in range(h):
            for dc in range(w):
                nr, nc = mr + dr, mc + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    output[nr][nc] = subgrid[dr][dc]

    return output
